<script lang="ts">
 import {onMount} from 'svelte';import {api} from '#lib/api.ts';import {session} from '#lib/session.svelte.ts';import {t} from '#lib/i18n/index.svelte.ts';import PageHead from '#lib/components/PageHead.svelte';import Dialog from '#lib/components/Dialog.svelte';import EmptyState from '#lib/components/EmptyState.svelte';import {formatBytes} from '#lib/format.ts';import {operationError} from '#lib/operations.ts';
 type Candidate={id:string;filesystem:string;filesystemUUID:string;arrayUUID:string;level:string;disks:string[];size:number;fingerprint:string;reason:string;encrypted?:boolean;encryptionUUID?:string};type Preview={candidate:Candidate;folders:string[];truncated:boolean;readOnly:boolean};
 const admin=$derived(['owner','admin'].includes(session.data?.user?.role??''));let list=$state<Candidate[]>([]),preview=$state<Preview|null>(null),name=$state(''),busy=$state(false),error=$state(''),registered=$state('');
 // Encrypted arrays: the password opens them read-only for the preview and for good at registration. Kept only while the dialogs are open.
 let unlocking=$state<Candidate|null>(null),password=$state('');
 async function load(){busy=true;error='';try{list=await api.get('/storage/import');}catch(e){error=operationError(e,t);}finally{busy=false;}}
 onMount(()=>{if(admin)load();});
 async function inspect(c:Candidate){if(c.encrypted&&!password){unlocking=c;error='';return;}busy=true;error='';try{preview=await api.post('/storage/import/preview',{id:c.id,fingerprint:c.fingerprint,password:c.encrypted?password:undefined});name='';unlocking=null;}catch(e){error=operationError(e,t);if(!c.encrypted)password='';}finally{busy=false;}}
 function closeAll(){preview=null;unlocking=null;password='';}
 const validName=$derived(/^[A-Za-z][A-Za-z0-9-]{0,11}$/.test(name));
 // Registers only on a click; the API still wants the new name repeated as confirmation.
 async function register(){if(!preview||!validName||busy)return;busy=true;error='';try{await api.post('/storage/import',{id:preview.candidate.id,fingerprint:preview.candidate.fingerprint,name,confirm:name,password:preview.candidate.encrypted?password:undefined});registered=name;closeAll();await load();}catch(e){error=operationError(e,t);}finally{busy=false;}}
</script>
{#if admin}<PageHead title={t('ops.import')} parent={{href:'/storage',label:t('nav.storage')}}>{#snippet actions()}<button class="btn" disabled={busy} onclick={load}>{t('ops.refresh')}</button>{/snippet}</PageHead><p class="muted">{t('ops.importHint')}</p>
{#if error}<p class="notice-error" role="alert">{error}</p>{/if}{#if registered}<p class="notice" role="status"><a href="/storage">{registered} →</a></p>{/if}
<section class="tile candidates">{#each list as c(c.id)}<article><div><strong>{c.level}{c.filesystem?` · ${c.filesystem.toUpperCase()}`:''}{#if c.encrypted} · {t('crypt.encrypted')}{/if}</strong><p class="mono">{c.id}</p><p>{c.disks.join(' · ')} · {formatBytes(c.size)}</p>{#if c.reason==='encrypted-partition'}<p class="notice-warn">{t('crypt.importRefused')}</p>{:else if c.reason}<p class="notice-warn">{c.reason}</p>{/if}</div><button class="btn btn-primary" disabled={busy||!!c.reason} onclick={()=>inspect(c)}>{t('ops.preview')}</button></article>{:else}<EmptyState inline title={busy?t('ops.loading'):t('ops.importNone')}/>{/each}</section>
{#if unlocking}<Dialog title={t('crypt.importTitle')} locked={busy} onclose={closeAll}><form onsubmit={e=>{e.preventDefault();if(unlocking&&password)inspect(unlocking);}}><p>{t('crypt.importText')}</p><label>{t('crypt.password')}<input class="field" type="password" autocomplete="off" bind:value={password} required/></label>{#if error}<p class="notice-error" role="alert">{error}</p>{/if}<div class="dialog-actions"><button type="button" class="btn" disabled={busy} onclick={closeAll}>{t('common.cancel')}</button><button type="submit" class="btn btn-primary" disabled={busy||!password}>{t('ops.preview')}</button></div></form></Dialog>{/if}
{#if preview}<Dialog title={t('ops.import')} locked={busy} onclose={closeAll}><p>{t('ops.importReady')}</p><p class="mono">{preview.candidate.filesystemUUID}</p><h3>{t('ops.folders')}</h3><ul>{#each preview.folders as folder(folder)}<li class="mono">{folder}</li>{/each}</ul>{#if preview.truncated}<p class="notice-warn">{t('ops.truncated')}</p>{/if}<form id="import-volume" onsubmit={e=>e.preventDefault()}><label>{t('ops.name')}<input class="field" bind:value={name} pattern={'[A-Za-z][A-Za-z0-9\\-]{0,11}'} maxlength="12" required/></label></form>{#if error}<p class="notice-error">{error}</p>{/if}<div class="dialog-actions"><button class="btn" disabled={busy} onclick={closeAll}>{t('common.cancel')}</button><button type="button" class="btn btn-warn" disabled={busy||!validName} onclick={register}>{t('ops.register')}</button></div></Dialog>{/if}
{:else}<p class="notice-error">{t('error.forbidden')}</p>{/if}
<style>.candidates{padding:var(--tile-pad);margin-top:var(--gap)}article{display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:14px;padding:16px 0;border-bottom:1px solid var(--border)}article p{overflow-wrap:anywhere;font-size:.85rem}article div{min-width:0}label{display:flex;flex-direction:column;gap:6px;margin-top:14px;font-size:.85rem}li{overflow-wrap:anywhere}</style>
